const rawOutput = $json.output || '';

let parsed = {};

try {
  const clean = String(rawOutput)
    .replace(/```json/g, '')
    .replace(/```/g, '')
    .trim();

  parsed = JSON.parse(clean);
} catch (error) {
  parsed = {
    error: true,
    message: 'No se pudo parsear el JSON del AI',
    rawOutput,
  };
}

function getProgramsNode() {
  try {
    return $('Normalize Program URLs').first();
  } catch (error) {}

  try {
    return $('Normalize Program URLs1').first();
  } catch (error) {}

  return null;
}

const programsNode = getProgramsNode();
const detectedPrograms = programsNode?.json?.detectedPrograms || [];
const programsSummary = programsNode?.json?.programsSummary || {
  totalDetected: detectedPrograms.length,
  importablePrograms: detectedPrograms.length,
};

const categoryCounts = detectedPrograms.reduce((acc, program) => {
  const category = String(program.parentCategory || 'uncategorized');
  acc[category] = (acc[category] || 0) + 1;
  return acc;
}, {});

const preferredCategories = Object.entries(categoryCounts)
  .sort((a, b) => b[1] - a[1])
  .map(([category]) => category)
  .filter((category) => !['cursos', 'course', 'courses'].includes(category));

const brandSlug = parsed?.brand?.slug || '';
const language = brandSlug ? (/-|universidad|fundacion|politecnico|tecmd|ean|minuto/i.test(brandSlug) ? 'es' : 'en') : 'es';

const programImportConfig = {
  language,
  includeParentCategories: preferredCategories.length > 0 ? preferredCategories : [],
  excludeParentCategories: ['cursos'],
  overwriteExisting: false,
};

return [
  {
    json: {
      ...parsed,
      detectedPrograms,
      programsSummary,
      programImportConfig,
    }
  }
];

const allCss = items
  .map(item => item.json.data || item.json.body || '')
  .join('\n');

const getVar = (name) => {
  const regex = new RegExp(`${name}\\s*:\\s*([^;]+);`, 'i');
  const match = allCss.match(regex);
  return match ? match[1].trim().replaceAll('"', '') : null;
};

const brand = {
  colors: {
    primary: getVar('--e-global-color-primary'),
    secondary: getVar('--e-global-color-secondary'),
    text: getVar('--e-global-color-text'),
    accent: getVar('--e-global-color-accent'),
  },
  fonts: {
    primary: getVar('--e-global-typography-primary-font-family'),
    secondary: getVar('--e-global-typography-secondary-font-family'),
    text: getVar('--e-global-typography-text-font-family'),
    accent: getVar('--e-global-typography-accent-font-family'),
  }
};

return [
  {
    json: {
      brand
    }
  }
];

const items = $input.all();

const first = items[0]?.json || {};
const second = items[1]?.json || {};
const third = items[2]?.json || {};

return [
  {
    json: {
      brandFromCssLinks: first.brand || null,
      brandFromBody: second.brandCandidate || null,
      brandFromLogo: third.imgSrc || null,
    }
  }
];

const rawOutput = $json.output || '';

let parsed;

try {
  parsed = JSON.parse(rawOutput);
} catch (error) {
  throw new Error('El output del bot no es un JSON válido: ' + error.message);
}

return [
  {
    json: parsed
  }
];

return items.map(item => {
  const rawMessage =
    item.json.body?.message ||
    item.json.message ||
    item.json.body?.brandName ||
    item.json.brandName ||
    "";

  const text = String(rawMessage).trim();

  const urlRegex = /(https?:\/\/[^\s"'<>]+|www\.[^\s"'<>]+)/i;
  const match = text.match(urlRegex);

  let normalizedUrl = null;

  if (match) {
    let url = match[0].trim();

    // quitar caracteres finales
    url = url.replace(/[),.;]+$/g, "");

    // agregar https si viene como www...
    if (!/^https?:\/\//i.test(url)) {
      url = `https://${url}`;
    }

    // limpiar a solo protocolo + dominio
    const domainMatch = url.match(/^(https?:\/\/[^\/?#]+)/i);

    if (domainMatch) {
      normalizedUrl = domainMatch[1].replace(/\/+$/, "");
    }
  }

  return {
    json: {
      ...item.json,
      normalizedUrl,
      hasValidUrl: Boolean(normalizedUrl),
      originalMessage: text
    }
  };
});

const input = items[0].json;
const meta = input.meta || [];

function getMeta(key, type = "name") {
  const found = meta.find(m => m[type] === key);
  return found?.content || null;
}

function getAllImages() {
  const imageKeys = [
    ["og:image", "property"],
    ["og:image:url", "property"],
    ["og:image:secure_url", "property"],
    ["twitter:image", "name"]
  ];

  const images = imageKeys
    .map(([key, type]) => getMeta(key, type))
    .filter(Boolean);

  return [...new Set(images)];
}

const cleaned = {
  title: getMeta("og:title", "property") || null,
  site_name: getMeta("og:site_name", "property") || null,
  description:
    getMeta("description", "name") ||
    getMeta("og:description", "property") ||
    null,
  abstract: getMeta("abstract", "name") || null,
  keywords: getMeta("keywords", "name")
    ? getMeta("keywords", "name")
        .split(",")
        .map(k => k.trim())
        .filter(Boolean)
    : [],
  official_website: getMeta("og:url", "property") || null,
  robots: getMeta("robots", "name") || null,
  generator: getMeta("Generator", "name") || null,
  images: getAllImages(),
  main_image: getAllImages()[0] || null
};

return [
  {
    json: cleaned
  }
];

const html = $input.first().json.data || '';

const baseUrl = $input.first().json.programUrl || '';

const styleTags = [...html.matchAll(/<style[^>]*>([\s\S]*?)<\/style>/gi)]
  .map(match => match[1].trim())
  .filter(Boolean);

const inlineStyles = [...html.matchAll(/style=["']([^"']+)["']/gi)]
  .map(match => match[1].trim())
  .filter(Boolean);

const cssLinks = [...html.matchAll(/<link[^>]+rel=["']?stylesheet["']?[^>]*>/gi)]
  .map(match => match[0])
  .map(tag => {
    const href = tag.match(/href=["']([^"']+)["']/i);
    return href ? href[1] : null;
  })
  .filter(Boolean)
  .map(link => {
    try {
      return baseUrl ? new URL(link, baseUrl).href : link;
    } catch {
      return link;
    }
  });

return [
  {
    json: {
      cssLinks: [...new Set(cssLinks)],
      styleTags,
      inlineStyles,
      totalCssLinks: cssLinks.length,
      totalStyleTags: styleTags.length,
      totalInlineStyles: inlineStyles.length
    }
  }
];

const input = $input.first().json;

const cssLinks = input.cssLinks || [];
const styleTags = input.styleTags || [];
const inlineStyles = input.inlineStyles || [];

const allInlineCss = [
  ...styleTags,
  ...inlineStyles
].join('\n');

/**
 * 1. Extraer colores del CSS inline y style tags
 */
const colors = [...allInlineCss.matchAll(
  /#(?:[0-9a-fA-F]{3,8})\b|rgba?\([^)]+\)|hsla?\([^)]+\)/g
)].map(m => m[0]);

/**
 * 2. Extraer variables CSS
 */
const cssVariables = [...allInlineCss.matchAll(
  /--([\w-]+)\s*:\s*([^;]+);/g
)].map(m => ({
  token: `--${m[1]}`,
  value: m[2].trim()
}));

/**
 * 3. Extraer fuentes desde font-family
 */
const fontFamiliesFromCss = [...allInlineCss.matchAll(
  /font-family\s*:\s*([^;]+);/gi
)].map(m => m[1].trim());

/**
 * 4. Extraer fuentes desde Google Fonts links
 */
const googleFonts = cssLinks
  .filter(url => url.includes('fonts.googleapis.com'))
  .map(url => {
    const match = url.match(/family=([^&]+)/i);
    if (!match) return null;

    return decodeURIComponent(match[1])
      .replace(/\+/g, ' ')
      .split(':')[0]
      .trim();
  })
  .filter(Boolean);

/**
 * 5. Detectar CSS importantes para siguiente paso
 */
const priorityCssLinks = cssLinks.filter(url =>
  url.includes('/uploads/elementor/css/post-') ||
  url.includes('/uploads/elementor/css/global') ||
  url.includes('/wp-content/themes/')
);

/**
 * 6. Organizar salida
 */
const unique = arr => [...new Set(arr.filter(Boolean))];

return [
  {
    json: {
      brandCandidate: {
        colors: unique(colors),
        fonts: unique([
          ...googleFonts,
          ...fontFamiliesFromCss
        ])
      },
      cssVariables,
      priorityCssLinks,
      allCssLinks: cssLinks,
      summary: {
        totalColorsFound: unique(colors).length,
        totalFontsFound: unique([
          ...googleFonts,
          ...fontFamiliesFromCss
        ]).length,
        totalCssVariables: cssVariables.length,
        totalPriorityCssLinks: priorityCssLinks.length
      }
    }
  }
];

const links = $input.first().json.cssLinks || [];

const rawProgramUrl =
  $('Webhook').first().json.body.message ||
  $('Preparar Mensaje').first().json.programUrl ||
  '';

if (!rawProgramUrl) {
  throw new Error('No encontré programUrl/baseUrl.');
}

const baseUrl = rawProgramUrl.startsWith('http')
  ? rawProgramUrl
  : `https://${rawProgramUrl}`;

return links.map(link => {
  const cleanLink = String(link).replaceAll('&amp;', '&');

  let finalUrl = cleanLink;

  if (cleanLink.startsWith('//')) {
    finalUrl = 'https:' + cleanLink;
  } else if (cleanLink.startsWith('/')) {
    finalUrl = baseUrl.replace(/\/$/, '') + cleanLink;
  } else if (!cleanLink.startsWith('http')) {
    finalUrl = baseUrl.replace(/\/$/, '') + '/' + cleanLink;
  }

  return {
    json: {
      originalCssUrl: link,
      cssUrl: finalUrl
    }
  };
});

