const images = $json.imgSrc || [];

const imgSrc = images
  .map(img => ({
    src: img.src || "",
    alt: img.alt || "",
    title: img.title || "",
    class: img.class || ""
  }))
  .filter(img => img.src);

return [
  {
    json: {
      imgSrc
    }
  }
];

const sitemaps = $json.sitemapindex?.sitemap || [];

return sitemaps.map(item => ({
  json: {
    sitemapUrl: item.loc
  }
}));

const patterns = [
  'program',
  'programa',
  'career',
  'careers',
  'curso',
  'cursos',
  'pregrado',
  'posgrado',
  'maestria',
  'doctorado',
  'faculty',
  'facultad',
  'academic',
  'academico',
  'oferta',
  'education',
  'educacion',
  'titulado',
  'degree',
  'degrees',
  'certification',
  'diplomado',
  'training'
];

return items
  .map(item => {
    const url = item.json.sitemapUrl.toLowerCase();

    const score = patterns.reduce((acc, pattern) => {
      return url.includes(pattern) ? acc + 1 : acc;
    }, 0);

    return {
      json: {
        sitemapUrl: item.json.sitemapUrl,
        score
      }
    };
  })
  .filter(item => item.json.score > 0)
  .sort((a, b) => b.json.score - a.json.score);

function getPathFromUrl(url) {
  return String(url || '')
    .replace(/^https?:\/\/[^/]+/i, '')
    .split('?')[0]
    .split('#')[0];
}

function getPathParts(url) {
  return getPathFromUrl(url)
    .split('/')
    .filter(Boolean);
}

function slugToTitle(slug = '') {
  return String(slug)
    .replace(/[-_]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .replace(/\b\w/g, (char) => char.toUpperCase());
}

function shouldKeepUrl(url = '') {
  return !/landing-page|copy|prueba/i.test(url);
}

const seen = new Set();
const detectedPrograms = [];

for (const item of items) {
  const urls = item.json.urlset?.url || [];

  for (const entry of urls) {
    const loc = typeof entry.loc === 'string' ? entry.loc.trim() : '';

    if (!loc || !shouldKeepUrl(loc)) {
      continue;
    }

    const parts = getPathParts(loc);
    const parentCategory = parts[0] || '';
    const slug = parts[parts.length - 1] || '';

    if (!slug) {
      continue;
    }

    const dedupeKey = slug + '::' + loc.toLowerCase();

    if (seen.has(dedupeKey)) {
      continue;
    }

    seen.add(dedupeKey);

    const title = slugToTitle(slug);

    detectedPrograms.push({
      parentCategory,
      parentCategoryLabel: slugToTitle(parentCategory),
      slug,
      titleFromSlug: title,
      url: loc,
      lastmod: entry.lastmod || null,
      seed: {
        title,
        fullTitle: title,
        slug,
        sourceWebsite: loc,
        programUrl: loc,
        template: 'DefaultLanding',
        status: 'draft'
      }
    });
  }
}

return [
  {
    json: {
      detectedPrograms,
      programsSummary: {
        totalDetected: detectedPrograms.length,
        importablePrograms: detectedPrograms.length
      }
    }
  }
];
